import * as React from 'react';
import {Paperclip,X} from 'lucide-react';
import {Button,Progress} from './basic';
import {Input,RadioGroup} from './forms';
export function Attachment({name,onRemove}:{name:string;onRemove?:()=>void}){return <span className="inline-flex max-w-full items-center gap-2 rounded-lg border border-line px-3 py-2 text-sm"><Paperclip aria-hidden className="size-4 shrink-0"/><span className="truncate">{name}</span>{onRemove&&<button onClick={onRemove} aria-label={'Remove '+name}><X className="size-4"/></button>}</span>}
export function Bubble({children,side='start'}:{children:React.ReactNode;side?:'start'|'end'}){return <div className={'max-w-[85%] rounded-2xl px-4 py-3 text-sm leading-relaxed '+(side==='end'?'ms-auto bg-ink text-paper':'bg-surface')}>{children}</div>}
export function Marker({children}:{children:React.ReactNode}){return <div className="my-5 flex items-center gap-3 text-xs text-muted"><hr className="flex-1 border-line"/>{children}<hr className="flex-1 border-line"/></div>}
export function Message({author,children,time}:{author:string;children:React.ReactNode;time?:string}){return <article className="space-y-2"><div className="flex gap-3 text-xs"><span className="font-semibold">{author}</span>{time&&<time className="text-muted">{time}</time>}</div><Bubble>{children}</Bubble></article>}
export function MessageScroller({children,label='Conversation'}:{children:React.ReactNode;label?:string}){return <div role="log" aria-label={label} aria-live="polite" tabIndex={0} className="max-h-64 space-y-4 overflow-y-auto rounded-xl border border-line p-4">{children}</div>}
export function Questionnaire({questions,onComplete}:{questions:{id:string;title:string;options:string[]}[];onComplete:(answers:Record<string,string>)=>void}){const [step,setStep]=React.useState(0),[answers,setAnswers]=React.useState<Record<string,string>>({});const q=questions[step];if(!q)return <p>No questions configured.</p>;return <form onSubmit={e=>{e.preventDefault();if(!answers[q.id])return;if(step===questions.length-1)onComplete(answers);else setStep(step+1)}} className="space-y-6"><Progress label="Your progress" value={step/questions.length*100}/><h3 className="font-editorial text-2xl">{q.title}</h3><RadioGroup label={q.title} value={answers[q.id]||''} onValueChange={value=>setAnswers(a=>({...a,[q.id]:value}))} options={q.options.map(o=>({label:o,value:o}))}/><div className="flex gap-3"><Button tone="outline" disabled={!step} onClick={()=>setStep(step-1)}>Previous</Button><Button type="submit" disabled={!answers[q.id]}>{step===questions.length-1?'Finish':'Next'}</Button></div></form>}

import * as React from 'react';
import {LoaderCircle} from 'lucide-react';
import {cx} from './utils';
export type ButtonProps=React.ButtonHTMLAttributes<HTMLButtonElement>&{tone?:'primary'|'secondary'|'outline'|'quiet'|'danger'|'accent';size?:'sm'|'md'|'lg';loading?:boolean};
export const Button=React.forwardRef<HTMLButtonElement,ButtonProps>(function Button({tone='primary',size='md',loading=false,disabled,children,className,type='button',...props},ref){
return <button ref={ref} type={type} disabled={disabled||loading} aria-busy={loading||undefined} className={cx('a-button',{'bg-ink text-paper hover:bg-ink/85':tone==='primary','bg-surface text-ink hover:bg-surface/70':tone==='secondary','border border-line bg-transparent text-ink':tone==='outline','bg-transparent text-ink hover:bg-surface':tone==='quiet','bg-danger text-white':tone==='danger','bg-gold text-[#181818]':tone==='accent'},{'min-h-9 px-3 text-xs':size==='sm','min-h-11 px-4 text-sm':size==='md','min-h-13 px-6 text-base':size==='lg'},className)} {...props}>{loading&&<LoaderCircle className="size-4 animate-spin motion-reduce:animate-none" aria-hidden/>}{children}</button>});
export function Badge({tone='neutral',className,children,...props}:React.HTMLAttributes<HTMLSpanElement>&{tone?:'neutral'|'success'|'warning'|'danger'}){return <span className={cx('inline-flex rounded-full px-2.5 py-1 text-xs font-medium',{'bg-surface text-ink':tone==='neutral','bg-success/10 text-success':tone==='success','bg-gold/20 text-ink':tone==='warning','bg-danger/10 text-danger':tone==='danger'},className)} {...props}>{children}</span>}
export function Card({className,...props}:React.HTMLAttributes<HTMLElement>){return <article className={cx('rounded-xl border border-line bg-card p-6',className)} {...props}/>}
export function CardHeader({className,...props}:React.HTMLAttributes<HTMLDivElement>){return <div className={cx('mb-5 space-y-2',className)} {...props}/>}
export function CardTitle({className,...props}:React.HTMLAttributes<HTMLHeadingElement>){return <h3 className={cx('text-xl font-medium tracking-tight',className)} {...props}/>}
export function CardDescription({className,...props}:React.HTMLAttributes<HTMLParagraphElement>){return <p className={cx('text-sm leading-relaxed text-muted',className)} {...props}/>}
export function CardFooter({className,...props}:React.HTMLAttributes<HTMLDivElement>){return <div className={cx('mt-6 flex flex-wrap items-center gap-3',className)} {...props}/>}
export const Separator=({className,...props}:React.HTMLAttributes<HTMLHRElement>)=><hr className={cx('my-5 border-line',className)} {...props}/>;
export function Skeleton({className,...props}:React.HTMLAttributes<HTMLDivElement>){return <div aria-hidden className={cx('h-4 rounded bg-surface animate-pulse motion-reduce:animate-none',className)} {...props}/>}
export function Spinner({label='Loading'}:{label?:string}){return <span role="status" className="inline-flex items-center gap-2 text-sm"><LoaderCircle className="size-4 animate-spin motion-reduce:animate-none" aria-hidden/>{label}</span>}
export function Alert({title,children,tone='info'}:{title:string;children?:React.ReactNode;tone?:'info'|'error'|'success'}){return <div role={tone==='error'?'alert':'status'} className={cx('rounded-xl border p-4 text-sm',tone==='error'?'border-danger/40 bg-danger/5':tone==='success'?'border-success/40 bg-success/5':'border-line bg-surface/50')}><p className="font-semibold">{title}</p>{children&&<div className="mt-2 leading-relaxed">{children}</div>}</div>}
export function Empty({title,children,action}:{title:string;children?:React.ReactNode;action?:React.ReactNode}){return <div className="rounded-xl border border-dashed border-line p-10 text-center"><h3 className="font-editorial text-2xl">{title}</h3><div className="mx-auto my-4 max-w-sm text-sm text-muted">{children}</div>{action}</div>}
export function Progress({value,label}:{value:number;label:string}){const current=Math.max(0,Math.min(100,value));return <div><div className="mb-2 flex justify-between text-sm"><span>{label}</span><span>{current}%</span></div><progress aria-label={label} value={current} max={100} className="h-2 w-full overflow-hidden rounded-full accent-terracotta"/></div>}
export function Avatar({src,name}:{src?:string;name:string}){const [failed,setFailed]=React.useState(false);return <span className="inline-flex size-10 items-center justify-center overflow-hidden rounded-full bg-surface text-sm font-semibold" role="img" aria-label={name}>{src&&!failed?<img src={src} alt="" onError={()=>setFailed(true)} className="size-full object-cover"/>:name.split(' ').map(n=>n[0]).slice(0,2).join('')}</span>}
export function AspectRatio({ratio=16/9,children,className}:{ratio?:number;children:React.ReactNode;className?:string}){return <div style={{aspectRatio:ratio}} className={cx('overflow-hidden rounded-xl',className)}>{children}</div>}
export const Kbd=({children}:{children:React.ReactNode})=><kbd className="rounded border border-line bg-surface px-1.5 py-0.5 font-mono text-xs">{children}</kbd>;
export const ButtonGroup=({children,label}:{children:React.ReactNode;label:string})=><div role="group" aria-label={label} className="flex flex-wrap gap-2">{children}</div>;
export function Item({title,description,action}:{title:string;description?:string;action?:React.ReactNode}){return <div className="flex items-center justify-between gap-4 border-b border-line py-4"><div><p className="font-medium">{title}</p>{description&&<p className="text-sm text-muted">{description}</p>}</div>{action}</div>}
export function Typography({children,as:Tag='p',editorial=false,className}:{children:React.ReactNode;as?:'h1'|'h2'|'h3'|'p';editorial?:boolean;className?:string}){return <Tag className={cx(editorial?'font-editorial':'font-sans',Tag==='h1'?'text-5xl leading-tight tracking-tight':Tag==='h2'?'text-3xl tracking-tight':Tag==='h3'?'text-xl':'leading-relaxed',className)}>{children}</Tag>}
export function Direction({dir,children}:{dir:'ltr'|'rtl';children:React.ReactNode}){return <div dir={dir}>{children}</div>}

import {clsx,type ClassValue} from 'clsx';
import {twMerge} from 'tailwind-merge';
export const cx=(...values:ClassValue[])=>twMerge(clsx(values));

import * as React from 'react';
import {Checkbox as RC,Switch as RS,Slider as SL,Select as SE,RadioGroup as RG,Toggle as TO,ToggleGroup as TG} from 'radix-ui';
import {Check,ChevronDown} from 'lucide-react';
import {DayPicker} from 'react-day-picker';
import {cx} from './utils';
export const Input=React.forwardRef<HTMLInputElement,React.InputHTMLAttributes<HTMLInputElement>>(function Input({className,...p},ref){return <input ref={ref} className={cx('a-input',className)} {...p}/>});
export const Textarea=React.forwardRef<HTMLTextAreaElement,React.TextareaHTMLAttributes<HTMLTextAreaElement>>(function Textarea({className,...p},ref){return <textarea ref={ref} rows={4} className={cx('a-input resize-y',className)} {...p}/>});
export function Label(p:React.LabelHTMLAttributes<HTMLLabelElement>){return <label {...p} className={cx('text-sm font-medium',p.className)}/>}
export function Field({label,hint,error,children}:{label:string;hint?:string;error?:string;children:React.ReactElement}){const id=React.useId();const description=[hint?id+'-hint':'',error?id+'-error':''].filter(Boolean).join(' ')||undefined;return <div className="grid gap-2"><Label htmlFor={id}>{label}</Label>{React.cloneElement(children as React.ReactElement<React.HTMLAttributes<HTMLElement>>,{id,'aria-describedby':description,'aria-invalid':error?true:undefined})}{hint&&<p id={id+'-hint'} className="text-xs text-muted">{hint}</p>}{error&&<p role="alert" id={id+'-error'} className="text-xs text-danger">{error}</p>}</div>}
export function InputGroup({prefix,suffix,children}:{prefix?:React.ReactNode;suffix?:React.ReactNode;children:React.ReactNode}){return <div className="flex items-center gap-2 rounded-lg border border-line bg-card px-3 [&_input]:border-0 [&_input]:bg-transparent"><span className="text-sm text-muted">{prefix}</span>{children}<span className="text-sm text-muted">{suffix}</span></div>}
export function Checkbox({label,...props}:React.ComponentProps<typeof RC.Root>&{label:string}){const id=React.useId();return <div className="flex items-center gap-3"><RC.Root id={id} {...props} className="flex size-5 shrink-0 items-center justify-center rounded border border-line bg-card data-[state=checked]:border-ink data-[state=checked]:bg-ink data-[state=checked]:text-paper disabled:opacity-40"><RC.Indicator><Check className="size-3.5"/></RC.Indicator></RC.Root><label htmlFor={id} className="text-sm">{label}</label></div>}
export function Switch({label,...props}:React.ComponentProps<typeof RS.Root>&{label:string}){const id=React.useId();return <div className="flex items-center gap-3"><RS.Root id={id} {...props} className="w-10 rounded-full border border-line bg-surface p-0.5 data-[state=checked]:bg-terracotta disabled:opacity-40"><RS.Thumb className="block size-4 rounded-full bg-card transition-transform data-[state=checked]:translate-x-4 motion-reduce:transition-none"/></RS.Root><label htmlFor={id} className="text-sm">{label}</label></div>}
export function RadioGroup({label,options,...props}:React.ComponentProps<typeof RG.Root>&{label:string;options:{value:string;label:string;disabled?:boolean}[]}){const uid=React.useId();return <RG.Root aria-label={label} {...props} className="grid gap-3">{options.map((o,i)=><div className="flex items-center gap-3" key={o.value}><RG.Item id={uid+i} value={o.value} disabled={o.disabled} className="flex size-5 items-center justify-center rounded-full border border-line disabled:opacity-40"><RG.Indicator className="size-2.5 rounded-full bg-terracotta"/></RG.Item><Label htmlFor={uid+i}>{o.label}</Label></div>)}</RG.Root>}
export function NativeSelect({options,...props}:React.SelectHTMLAttributes<HTMLSelectElement>&{options:{value:string;label:string;disabled?:boolean}[]}){return <select {...props} className={cx('a-input',props.className)}>{options.map(o=><option key={o.value} {...o}>{o.label}</option>)}</select>}
export function Select({label,options,placeholder='Choose an option',...props}:React.ComponentProps<typeof SE.Root>&{label:string;placeholder?:string;options:{value:string;label:string;disabled?:boolean}[]}){return <SE.Root {...props}><SE.Trigger aria-label={label} className="a-input flex items-center justify-between gap-3"><SE.Value placeholder={placeholder}/><SE.Icon><ChevronDown className="size-4"/></SE.Icon></SE.Trigger><SE.Portal><SE.Content className="a-popup min-w-[var(--radix-select-trigger-width)]" position="popper" sideOffset={6}><SE.Viewport>{options.map(o=><SE.Item key={o.value} value={o.value} disabled={o.disabled} className="relative flex cursor-pointer items-center gap-2 rounded-md px-3 py-2 text-sm outline-none data-[highlighted]:bg-surface data-[disabled]:opacity-40"><SE.ItemText>{o.label}</SE.ItemText><SE.ItemIndicator><Check className="size-3.5"/></SE.ItemIndicator></SE.Item>)}</SE.Viewport></SE.Content></SE.Portal></SE.Root>}
export function Slider({label,...props}:React.ComponentProps<typeof SL.Root>&{label:string}){const values=props.value||props.defaultValue||[50];return <SL.Root {...props} defaultValue={props.defaultValue||(!props.value?[50]:undefined)} className="relative flex h-8 w-full touch-none items-center"><SL.Track className="relative h-1.5 grow rounded-full bg-surface"><SL.Range className="absolute h-full rounded-full bg-terracotta"/></SL.Track>{values.map((_,i)=><SL.Thumb key={i} aria-label={values.length>1?label+' '+(i+1):label} className="block size-5 rounded-full border border-line bg-card shadow-sm"/>)}</SL.Root>}
export function Toggle({children,...props}:React.ComponentProps<typeof TO.Root>){return <TO.Root {...props} className="a-button min-h-10 border border-line px-3 text-sm data-[state=on]:bg-ink data-[state=on]:text-paper">{children}</TO.Root>}
export function ToggleGroup({label,options,value,onValueChange}:{label:string;options:string[];value?:string;onValueChange?:(v:string)=>void}){return <TG.Root type="single" aria-label={label} value={value} onValueChange={onValueChange} className="inline-flex gap-1 rounded-lg bg-surface p-1">{options.map(o=><TG.Item key={o} value={o} className="rounded-md px-3 py-2 text-sm data-[state=on]:bg-card">{o}</TG.Item>)}</TG.Root>}
export function Calendar(props:React.ComponentProps<typeof DayPicker>){return <DayPicker {...props} className="a-calendar" showOutsideDays/>}
export function DatePicker(props:Omit<React.InputHTMLAttributes<HTMLInputElement>,'type'>){return <Input {...props} type="date"/>}
export function Combobox({label,options,...props}:React.InputHTMLAttributes<HTMLInputElement>&{label:string;options:string[]}){const id=React.useId();return <><Input {...props} aria-label={label} list={id}/><datalist id={id}>{options.map(o=><option key={o} value={o}/>)}</datalist></>}
export function InputOTP({length=6,label='Verification code',value,onChange,disabled}:{length?:number;label?:string;value:string;onChange:(v:string)=>void;disabled?:boolean}){return <Input aria-label={label} inputMode="numeric" autoComplete="one-time-code" value={value} disabled={disabled} maxLength={length} pattern={'[0-9]{'+length+'}'} onChange={e=>onChange(e.target.value.replace(/\D/g,'').slice(0,length))} className="max-w-64 text-center font-mono text-xl tracking-[0.5em]"/>}

@import "tailwindcss";
@source "./**/*.{ts,tsx}";
@theme {
 --color-paper:#f4f1e9;--color-ink:#20201d;--color-muted:#656158;--color-line:#d2ccc0;
 --color-surface:#e8e3d8;--color-card:#faf8f2;--color-terracotta:#ac4333;--color-gold:#edbd52;
 --color-danger:#a32925;--color-success:#326145;
 --font-sans:'DM Sans Variable',Arial,sans-serif;--font-editorial:'Lora Variable',Georgia,serif;
}
@layer base {
 *{border-color:var(--color-line)}
 body{background:var(--color-paper);color:var(--color-ink);font-family:var(--font-sans);margin:0;-webkit-font-smoothing:antialiased}
 button:not(:disabled),summary{cursor:pointer}
 :focus-visible{outline:2px solid var(--color-terracotta);outline-offset:4px}
}
@layer components {
 .a-button{@apply inline-flex shrink-0 items-center justify-center gap-2 rounded-lg font-medium transition-colors disabled:pointer-events-none disabled:opacity-45 focus-visible:outline-2 focus-visible:outline-offset-4}
 .a-input{@apply min-h-11 w-full rounded-lg border border-line bg-card px-3 py-2 text-sm text-ink placeholder:text-muted disabled:opacity-50 aria-invalid:border-danger}
 .a-overlay{@apply fixed inset-0 z-50 bg-black/40 backdrop-blur-xs}
 .a-popup{@apply z-50 rounded-xl border border-line bg-card p-2 text-ink shadow-xl}
}
[data-theme=dark]{--color-paper:#191a18;--color-ink:#eeeade;--color-muted:#b8b3a8;--color-line:#45463f;--color-surface:#30312c;--color-card:#22241f;--color-terracotta:#e69477;--color-danger:#f2938c;--color-success:#8fc8a4}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
